def admit_title_scene_source(source,title_source,reused_sources,portrait_registry_source,portrait_provider_source):
    """Full source/AST/CodeType preparation only, not dynamic acceptance."""
    tree=ast.parse(source)
    if ast.dump(tree,include_attributes=False)!=EXPECTED_MODULE_AST:
        raise ValueError('complete admitted title continuation source differs')
    if ast.dump(ast.parse(title_source),include_attributes=False)!=EXPECTED_TITLE_AST:
        raise ValueError('complete current original title module differs')
    if set(reused_sources)!=set(EXPECTED_REUSED_ASTS):raise ValueError('all finite title dependency modules required')
    for path,expected in EXPECTED_REUSED_ASTS.items():
        nodes={node.name:node for node in ast.parse(reused_sources[path]).body if isinstance(node,ast.FunctionDef)}
        for name,source_ast in expected.items():
            if name not in nodes or ast.dump(nodes[name],include_attributes=False)!=source_ast:
                raise ValueError('complete synchronous title child differs: '+name)
    registry=ast.parse(portrait_registry_source)
    values={node.targets[0].id:ast.literal_eval(node.value) for node in registry.body
        if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name)
        and node.targets[0].id in ('EXPECTED_MODULE_AST','EXPECTED_REUSED_SOURCE')}
    if ast.dump(ast.parse(portrait_provider_source),include_attributes=False)!=values['EXPECTED_MODULE_AST']:
        raise ValueError('existing exact portrait provider registration differs')
    metadata={node.targets[0].id:ast.literal_eval(node.value) for node in tree.body
        if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name)
        and node.targets[0].id in ('MAIN_ENTRIES','VIEW_SPECS','SERVICE_NAMES')}
    definition=next(node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name=='_title_tree')
    namespace=dict(ast=ast,copy=copy,_dump=lambda node:ast.dump(node,include_attributes=False),
        EXPECTED_TITLE_AST=EXPECTED_TITLE_AST,**metadata)
    exec(compile(ast.Module(body=[definition],type_ignores=[]),'<title full source inverse>','exec'),namespace)
    original=ast.parse(title_source)
    derived=namespace['_title_tree'](original)
    original_code=compile(original,'<original title whole module>','exec',dont_inherit=True)
    derived_code=compile(derived,'<cooperative title whole module>','exec',dont_inherit=True)
    for name in metadata['VIEW_SPECS']:
        plain=[code for code in original_code.co_consts if isinstance(code,types.CodeType) and code.co_name==name]
        lifted=[code for code in derived_code.co_consts if isinstance(code,types.CodeType) and code.co_name==name]
        if len(plain)!=1 or len(lifted)!=1 or plain[0].co_flags&32 or not lifted[0].co_flags&32:
            raise ValueError('each title view must be a real complete original FN and derived generator')
    return dict(confidence='confirmed_source_only',new_Main_targets=tuple(metadata['MAIN_ENTRIES']),
        complete_FN_inverses=6,whole_title_module_inverse=True,propagation_expressions=20,
        actual_parent_CALL_pairs=19,existing_services_reused=metadata['SERVICE_NAMES'],
        same_Scene_and_real_CALL_slots=True,new_business_algorithms=0,new_wait_types=0,new_CALL_slots=0,
        strict_pending_unchanged=46004,formal_credit=0,game=False,fixture=False,normal_API=False,
        native=False,hash=False,old_replay=False,public_modified=False)
